source.ruleBookContentDecoder:
@js:
try {
    var Magua = new JavaImporter();
    Magua.importPackage(
        Packages.java.io,
        Packages.android.graphics
    );

    with (Magua) {
        if (baseUrl.search("w=")!=-1 ) {
            var num = baseUrl.match(/\d+/g).slice(-1);
            var img = BitmapFactory.decodeByteArray(result, 0, result.length);
            var height = img.getHeight();
            var width = img.getWidth();
            var x = width / num;
            var newImg = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888);
            let canvas = new Canvas(newImg);
            for (let i = 1; i <= num; i++) {
                canvas.drawBitmap(Bitmap.createBitmap(img, x * (i - 1), 0, x, height), width - x * i, 0, null);
            }
            var newbit = new ByteArrayOutputStream();
            newImg.compress(Bitmap.CompressFormat.PNG, 100, newbit);
            newbit.toByteArray();
        } else {
            result;
        }
    }
} catch (err) {
    ycy.toast(err.toString());
}

